public static class LycarionLogger
{
    private static volatile LycarionLogLevel level = LycarionLogLevel.Info;
    /// <summary>全局日志级别：低于此级别的日志会被忽略。 </summary>
    public static LycarionLogLevel Level
    {
        get => level;
        set => level = value;
    }

    /// <summary>启动日志服务器（浏览器调试页 + WebSocket），并在控制台打印访问地址。返回 false 表示端口已被另一个 Logger 实例占用。重复调用直接返回 true，此时传入的新端口会被忽略。端口传 0 表示自动分配空闲端口。 </summary>
    public static bool Initialize(int port = 8080)
    {
        lock (lifecycleLock)
        {
            if (running)
            {
                // port 0 表示"随便哪个端口", 已在运行时无需提示端口不一致
                if (port != 0 && runningPort != port)
                    Warn(ModuleName, $"Already initialized on port {runningPort}, ignoring requested port {port}");
                return true;
            }

            // 端口 0 由 OS 分配, 不存在跨实例冲突, 因此不需要按端口加跨进程互斥体
            Mutex? mutex = null;
            if (port != 0)
            {
                bool createdNew;
                mutex = new Mutex(true, $"Global\\Lycarion_WebSocketLogger:{port}", out createdNew);
                if (!createdNew)
                {
                    // 互斥体已存在: 尝试接管(含上次进程异常退出遗留的 abandoned)
                    try
                    {
                        if (!mutex.WaitOne(0))
                        {
                            mutex.Close();
                            NotifyPortInUse(port);
                            return false;
                        }
                    }
                    catch (AbandonedMutexException) { }   // abandoned: 已接管所有权, 继续启动
                }
            }

            try
            {
                serverMutex = mutex;
                LoggerCommandRegistry.Initialize();
                StartupUtc = DateTime.UtcNow;
                LogQueue.StartSession();   // 回放 Initialize 之前/上次 Shutdown 之后的日志
                cts = new CancellationTokenSource();
                var token = cts.Token;

                WebSocketServer.Start(port);
                senderTask = Task.Run(() => LogQueue.RunSenderAsync(msg => WebSocketServer.BroadcastAsync(msg), token));

                HookExitEvents();
                running = true;
                runningPort = WebSocketServer.Port;   // 端口 0 时取 OS 实际分配值
                Info(ModuleName, "Logger initialized");
                Console.WriteLine($"[LycarionLogger] listening on http://localhost:{runningPort}/");
            }
            catch
            {
                // 启动中途失败: 释放互斥体并回滚状态, 避免留下半初始化实例/遗留锁
                if (mutex != null)
                {
                    try { mutex.ReleaseMutex(); } catch { }
                    mutex.Close();
                }
                serverMutex = null;
                senderTask = null;
                cts = null;
                throw;
            }
            return true;
        }
    }

    /// <summary>停止日志服务器并关闭浏览器页面连接。可重复调用；进程退出时会自动调用。 </summary>
    public static void Shutdown()
    {
        lock (lifecycleLock)
        {
            if (!running || shuttingDown)
                return;   // 幂等: 未初始化/重复 Shutdown 不再抛(CompleteAdding 二次调用会抛)
            shuttingDown = true;
            try
            {
                Info(ModuleName, "Logger shutdown");
                LogQueue.CompleteAdding();
                // 等队列排空(积压日志完整送达); 慢客户端由写超时踢除, 最长等 4s
                senderTask?.Wait(4000);
                cts?.Cancel();
                try { serverMutex?.ReleaseMutex(); } catch { }   // 必须释放所有权, 否则互斥体 abandoned, 下次 Initialize 拿不到
                serverMutex?.Close();
                serverMutex = null;
                WebSocketServer.Stop();
            }
            catch { }   // 进程退出路径: Shutdown 不向上抛
            finally
            {
                senderTask = null;
                cts = null;   // 不 Dispose: 已取消的 senderTask 可能仍持有 Token
                running = false;
                runningPort = 0;
                shuttingDown = false;
            }
        }
    }

    /// <summary>写入一条日志（受全局 Level 过滤）。 </summary>
    public static void Log(LycarionLogLevel logLevel, string message)
    {
        if (!ShouldLog(logLevel, Level))
            return;

        LogQueue.Enqueue(new LogEntry(logLevel, null, message));
    }

    /// <summary>写入指定级别、带模块标签的日志。 </summary>
    public static void Log(LycarionLogLevel logLevel, string module, string message)
    {
        if (!ShouldLog(logLevel, Level))
            return;

        LogQueue.Enqueue(new LogEntry(logLevel, module, message));
    }

    /// <summary>判断该级别日志当前是否会被记录（可在拼接消息前先判断，避免热路径无谓分配）。 </summary>
    public static bool IsEnabled(LycarionLogLevel logLevel) => ShouldLog(logLevel, Level);

    /// <summary>写入一条不带级别与时间戳的原始行。 </summary>
    public static void Raw(string msg) => LogQueue.Enqueue(new LogEntry(LycarionLogLevel.Info, null, msg, true));
    /// <summary>写入 Verbose 级别日志。 </summary>
    public static void Verbose(string msg) => Log(LycarionLogLevel.Verbose, msg);
    /// <summary>写入 Debug 级别日志。 </summary>
    public static void Debug(string msg) => Log(LycarionLogLevel.Debug, msg);
    /// <summary>写入 Info 级别日志。 </summary>
