    /// <summary>写入带模块标签的 Verbose 级别日志。 </summary>
    public static void Verbose(string module, string msg) => Log(LycarionLogLevel.Verbose, module, msg);
    /// <summary>写入带模块标签的 Debug 级别日志。 </summary>
    public static void Debug(string module, string msg) => Log(LycarionLogLevel.Debug, module, msg);
    /// <summary>写入带模块标签的 Info 级别日志。 </summary>
    public static void Info(string module, string msg) => Log(LycarionLogLevel.Info, module, msg);
    /// <summary>写入带模块标签的 Warn 级别日志。 </summary>
    public static void Warn(string module, string msg) => Log(LycarionLogLevel.Warn, module, msg);
    /// <summary>写入带模块标签的 Error 级别日志。 </summary>
    public static void Error(string module, string msg) => Log(LycarionLogLevel.Error, module, msg);
    /// <summary>写入带模块标签的 Error 级别日志，消息包含异常堆栈。 </summary>
    public static void Error(string module, Exception ex) => Log(LycarionLogLevel.Error, module, $"{ex}\n");

    internal static bool ShouldLog(LycarionLogLevel level, LycarionLogLevel current) => level >= current;
    internal static DateTime StartupUtc { get; private set; }
    internal static int QueueCount => LogQueue.Count;

    // 生命周期状态: Initialize/Shutdown 全流程在 lifecycleLock 内串行, 保证 running/senderTask 等一致
    private static readonly object lifecycleLock = new();
    private static CancellationTokenSource? cts;
    private static Task? senderTask;
    private static Mutex? serverMutex;
    private static bool running;
    private static int runningPort;
    private static bool shuttingDown;
    private static bool exitHooksHooked;
    private const string ModuleName = "Logger";

    // 退出钩子只挂载一次: 反复 Initialize/Shutdown 不再累积处理器
    static void HookExitEvents()
    {
        if (exitHooksHooked)
            return;
        exitHooksHooked = true;
        AppDomain.CurrentDomain.UnhandledException += (sender, e) => { Shutdown(); };
        AppDomain.CurrentDomain.ProcessExit += (sender, e) => { Shutdown(); };
    }

    // 端口被其他实例占用: 控制台提醒 + 连已有实例发 /notify 请求(浏览器可见 Warn [Server])
    static void NotifyPortInUse(int port)
    {
        var message = $"port {port} already in use by another Logger instance";
        Console.WriteLine($"[LycarionLogger] {message}");
        try { NotifyViaExistingInstance(port, message); } catch { }
    }

    static void NotifyViaExistingInstance(int port, string message)
    {
        // 无需 WebSocket 握手/掩码帧: 已有实例在 HTTP 层识别 /notify 路径并广播 Warn
        using var client = new TcpClient();
        client.Connect(IPAddress.Loopback, port);
        using var stream = client.GetStream();

        var request = $"GET /notify?m={Uri.EscapeDataString(message)} HTTP/1.1\r\nHost: localhost:{port}\r\n\r\n";
        var requestBytes = Encoding.ASCII.GetBytes(request);
        stream.Write(requestBytes, 0, requestBytes.Length);
        // 立即 Close 会丢弃 OS 发送缓冲(请求发不出去); linger 2s 让 OS 发完再关
        client.Client.LingerState = new LingerOption(true, 2);
        Thread.Sleep(200);   // 兜底: 等 OS 发出请求(某些宿主上 linger 不可靠)
    }
}

