#region file: LogEntry.cs
/// <summary>一条日志（时间戳与线程在入队时定格）。 </summary>
file readonly struct LogEntry
{
    public readonly LycarionLogLevel Level;
    public readonly DateTime Timestamp;
    public readonly string? Module;
    public readonly string Message;
    public readonly bool Raw;
    public readonly int ThreadId;

    public LogEntry(LycarionLogLevel level, string? module, string message, bool raw = false)
    {
        Level = level;
        Module = module;
        Message = message;
        Raw = raw;
        Timestamp = DateTime.Now;
        ThreadId = Environment.CurrentManagedThreadId;
    }

    private const string TimeFormat = "yyyy-MM-dd HH:mm:ss.fff";

    /// <summary>协议 v2 行: Level|时间|线程|模块|raw标记|消息（消息为最后一段, 不再转义）。 </summary>
    public override string ToString() => string.Concat(
        Level.ToString(), "|",
        Timestamp.ToString(TimeFormat), "|",
        ThreadId.ToString(), "|",
        EscapeField(Module), "|",
        Raw ? "1" : "0", "|",
        Message);

    /// <summary>模块字段转义: 反斜杠/竖线/换行, 避免破坏行协议分段。 </summary>
    static string EscapeField(string? value)
    {
        if (value == null || value.Length == 0)
            return "";
        if (value.IndexOfAny(['\\', '|', '\r', '\n']) < 0)
            return value;
        return value
            .Replace("\\", "\\\\")
            .Replace("|", "\\|")
            .Replace("\r", "\\r")
            .Replace("\n", "\\n");
    }
}
#endregion

#region file: LogQueue.cs
/// <summary>有界发送队列：生产者与消费者解耦；满时丢最旧日志，防止日志洪峰 OOM。 </summary>
file static class LogQueue
{
    private const int MaxQueue = 10000;
    private const int MaxPending = 2000;
    private static readonly object sync = new();
    private static BlockingCollection<LogEntry> queue = new();
    private static readonly Queue<LogEntry> pending = new();   // 未运行期间(Initialize 之前/Shutdown 之后)暂存, 重启后回放
    private static volatile bool accepting = true;

    internal static int Count => queue.Count + PendingCount;
    private static int PendingCount { get { lock (sync) return pending.Count; } }

    /// <summary>开始新会话：复用未关闭的队列(首次启动保留 Initialize 之前的日志), 关闭过则重建并回放暂存日志。 </summary>
    internal static void StartSession()
    {
        lock (sync)
        {
            if (queue.IsAddingCompleted)
                queue = new BlockingCollection<LogEntry>();
            while (pending.Count > 0)
                EnqueueCore(pending.Dequeue());
            accepting = true;
        }
    }

    internal static void CompleteAdding()
    {
        lock (sync)
        {
            accepting = false;
            queue.CompleteAdding();
        }
    }

    internal static void Enqueue(LogEntry log)
    {
        if (accepting)
        {
            try { EnqueueCore(log); return; }
            catch (InvalidOperationException) { }   // 与 CompleteAdding 竞争: 转入暂存
        }
        lock (sync)
        {
            if (accepting)
            {
                try { EnqueueCore(log); return; }
                catch (InvalidOperationException) { }
            }
            AddPendingCore(log);
        }
    }

    static void EnqueueCore(LogEntry log)
    {
        if (queue.Count >= MaxQueue)
            queue.TryTake(out _);   // 满时丢最旧保最新: 调试场景"最新最重要"
        queue.Add(log);
    }

    static void AddPendingCore(LogEntry log)
    {
        if (pending.Count >= MaxPending)
            pending.Dequeue();   // 未运行期间的日志同样有界
        pending.Enqueue(log);
    }

    /// <summary>消费者：逐条取出并广播。 </summary>
    internal static async Task RunSenderAsync(Func<string, Task> broadcast, CancellationToken ct)
    {
        foreach (var log in queue.GetConsumingEnumerable(ct))
        {
            try { await broadcast(log.ToString()); }
            catch { await Task.Delay(200, ct); }   // 广播失败时退避, 避免错误期间忙等
        }
    }
}
#endregion

