#region file: ArgumentBinder.cs
file static class ArgumentBinder
{
    private const string ModuleName = "ArgumentBinder";

    public static bool TryCreateInvoker(MethodInfo method, out List<string> parameterInfo, out Action<string[]> invoker, out List<ParamSpec> paramSpecs)
    {
        parameterInfo = new List<string>();
        paramSpecs = new List<ParamSpec>();
        invoker = _ => { };
        var compiled = BuildCompiledInvoker(method);   // 预编译委托, 替代每次反射 Invoke(实测快 3x)
        var parameters = method.GetParameters();
        if (parameters.Length == 0)
        {
            invoker = _ =>
            {
                try { compiled(Array.Empty<object>()); }
                catch (Exception ex) { LycarionLogger.Error("Command", $"Command failed: {ex}\n"); }
            };
            return true;
        }

        bool hasParams = false;
        bool hasRawString = false;
        for (int i = 0; i < parameters.Length; i++)
        {
            var p = parameters[i];
            var isParamsArray = i == parameters.Length - 1 && p.IsDefined(typeof(ParamArrayAttribute), false);
            var type = isParamsArray ? p.ParameterType.GetElementType() : p.ParameterType;

            if (type != typeof(int) &&
                type != typeof(float) &&
                type != typeof(double) &&
                type != typeof(long) &&
                type != typeof(decimal) &&
                type != typeof(string) &&
                type != typeof(bool) &&
                type != typeof(RawString) &&
                !type!.IsEnum)
            {
                LycarionLogger.Error(ModuleName, $"Parameter {p.Name} has unsupported type: {type.Name}");
                return false;
            }
            if (type == typeof(RawString) && i != parameters.Length - 1)
            {
                LycarionLogger.Error(ModuleName, $"Parameter {p.Name} with type RawString must be last parameter");
                return false;
            }
            if (type == typeof(RawString) && isParamsArray)
            {
                LycarionLogger.Error(ModuleName, $"Parameter {p.Name} with type RawString cannot as params array");
                return false;
            }

            var defaultValue = p.HasDefaultValue ? $" = {FormatDefaultValue(p.DefaultValue, p.ParameterType)}" : "";
            var typeName = type switch
            {
                _ when type == typeof(int) => "int",
                _ when type == typeof(float) => "float",
                _ when type == typeof(double) => "double",
                _ when type == typeof(long) => "long",
                _ when type == typeof(decimal) => "decimal",
                _ when type == typeof(string) => "string",
                _ when type == typeof(bool) => "bool",
                _ => type.Name
            };

            if (isParamsArray)
            {
                hasParams = true;
                typeName = $"params {typeName}[]";
            }
            else if (type == typeof(RawString))
                hasRawString = true;

            var displayStr = $"{typeName} {p.Name}{defaultValue}";
            parameterInfo.Add(displayStr);

            string kind = type switch
            {
                _ when type == typeof(int) => "int",
                _ when type == typeof(float) => "float",
                _ when type == typeof(double) => "double",
                _ when type == typeof(long) => "long",
                _ when type == typeof(decimal) => "decimal",
                _ when type == typeof(string) => "string",
                _ when type == typeof(bool) => "bool",
                _ when type == typeof(RawString) => "raw",
                _ => type.IsEnum ? "enum" : type.Name
            };
            if (isParamsArray)
                kind = "params";
            paramSpecs.Add(new ParamSpec
            {
                Name = p.Name ?? "",
                Kind = kind,
                Values = type.IsEnum ? Enum.GetNames(type) : null,
                Default = p.HasDefaultValue ? FormatDefaultValue(p.DefaultValue, p.ParameterType) : null,
                Display = displayStr
            });
        }

        invoker = args =>
        {
            if ((!hasParams && !hasRawString) && args.Length > parameters.Length)
            {
                LycarionLogger.Warn("Too many arguments");
                return;
            }

            object[] invokeArgs = new object[parameters.Length];
            for (int i = 0; i < parameters.Length; i++)
            {
                var p = parameters[i];

                if (hasParams && i == parameters.Length - 1)
                {
                    var elementType = p.ParameterType.GetElementType()!;
                    var count = Math.Max(0, args.Length - i);
                    var paramsArray = Array.CreateInstance(elementType, count);

                    for (int j = 0; j < count; j++)
                    {
                        try { paramsArray.SetValue(ConvertArg(args[i + j], elementType), j); }
                        catch (Exception e) { LycarionLogger.Warn("Command", $"Invalid params argument at {i + j}: {e.Message}"); return; }
                    }
                    invokeArgs[i] = paramsArray;
                    break;
                }
                else if (p.ParameterType == typeof(RawString))
                {
                    var rawContent = i < args.Length ? string.Join(" ", args.Skip(i)) : "";
                    invokeArgs[i] = new RawString(rawContent);
                    break;
                }

                if (i < args.Length)
                {
                    try { invokeArgs[i] = ConvertArg(args[i], p.ParameterType); }
                    catch (Exception e) { LycarionLogger.Warn("Command", $"Invalid argument at {i}: {args[i]}, {e.Message}"); return; }
                }
                else if (p.HasDefaultValue)
                {
                    invokeArgs[i] = p.DefaultValue!;
                }
                else
                {
                    LycarionLogger.Warn("Command", $"Missing required argument: {p.Name}");
                    return;
                }
            }

            try { compiled(invokeArgs); }
            catch (Exception ex) { LycarionLogger.Error("Command", $"Command failed: {ex}\n"); }
        };

        return true;

        static Func<object[], object> BuildCompiledInvoker(MethodInfo method)
        {
            var args = Expression.Parameter(typeof(object[]), "args");
            var callArgs = method.GetParameters().Select((p, i) =>
                (Expression)Expression.Convert(Expression.ArrayIndex(args, Expression.Constant(i)), p.ParameterType));
            var call = Expression.Call(method, callArgs);
            if (method.ReturnType == typeof(void))
                return Expression.Lambda<Func<object[], object>>(
                    Expression.Block(call, Expression.Constant(null, typeof(object))), args).Compile();
            return Expression.Lambda<Func<object[], object>>(
                Expression.Convert(call, typeof(object)), args).Compile();
        }

        static object ConvertArg(string arg, Type type) => type switch
        {
            _ when type == typeof(string) => arg,
            _ when type == typeof(int) => int.Parse(arg, CultureInfo.InvariantCulture),
            _ when type == typeof(float) => float.Parse(arg, CultureInfo.InvariantCulture),
            _ when type == typeof(double) => double.Parse(arg, CultureInfo.InvariantCulture),
            _ when type == typeof(long) => long.Parse(arg, CultureInfo.InvariantCulture),
            _ when type == typeof(decimal) => decimal.Parse(arg, CultureInfo.InvariantCulture),
            _ when type == typeof(bool) => arg != "false" && arg != "f" && arg != "0",
            _ when type == typeof(RawString) => new RawString(arg),
            _ when type.IsEnum =>
                Enum.IsDefined(type, arg)
                    ? Enum.Parse(type, arg, true)
                    : throw new Exception($"'{arg}' is not a valid value for {type.Name}"),
            _ => throw new Exception()
        };

        static string FormatDefaultValue(object? value, Type type) => value switch
        {
            null => "null",
            float f => $"{f.ToString()}f",
            double d => $"{d.ToString()}d",
            long l => $"{l.ToString()}L",
            decimal m => $"{m.ToString()}m",
            string s => $"\"{s}\"",
            bool b => b.ToString().ToLower(),
            RawString rs => $"\"{rs}\"",
            Enum e => e.ToString(),
            _ => value.ToString()!
        };
    }
}
#endregion

#region file: LoggerCommandRegistry.cs
file static class LoggerCommandRegistry
{
    public static readonly Dictionary<string, Command> Commands = new(StringComparer.OrdinalIgnoreCase);
    internal const string ModuleName = "LoggerCommandRegistry";

    internal static void Initialize()
    {
        Commands.Clear();   // 重新扫描: 清掉上一会话的残留命令, 重复名检测才有意义
        var asm = Assembly.GetCallingAssembly();
        var types = asm.GetTypes();
        var methods = types.SelectMany(t => t.GetMethods(BindingFlags.Public | BindingFlags.Static));

        foreach (var method in methods)
        {
            var attr = method.GetCustomAttribute<LoggerCommandAttribute>();
            if (attr == null)
                continue;

            if (!method.IsStatic || method.ReturnType != typeof(void))
            {
                LycarionLogger.Warn(ModuleName, $"Method {method.Name} must be static and return void as Logger Command!");
                continue;
            }

            var name = attr.Name;
            if (HasMetaDelimiters(name))
            {
                // 命令名会进入 @cmds 元数据, 分隔符会破坏前端解析
                LycarionLogger.Warn(ModuleName, $"Command name '{name}' contains a reserved @cmds delimiter, skipped");
                continue;
            }

            if (!ArgumentBinder.TryCreateInvoker(method, out var parameterInfo, out var invoker, out var paramSpecs))
                continue;

            if (Commands.ContainsKey(name))
                LycarionLogger.Warn(ModuleName, $"Duplicate command name '{name}', previous registration is overridden");

            var metaProblem = FindMetaProblem(paramSpecs);
            if (metaProblem != null)
                LycarionLogger.Warn(ModuleName, $"Command '{name}' has unsafe completion metadata: {metaProblem}");

            Commands[name] = new Command(name, attr.Description, parameterInfo, invoker, paramSpecs, attr.Group);
        }
    }

    // @cmds 协议用这些字符分隔: cmd~param:kind:display[:values],...;...
    static readonly char[] MetaDelimiters = ['~', ':', ',', '|', ';'];

    internal static bool HasMetaDelimiters(string text) =>
        !string.IsNullOrEmpty(text) && text.IndexOfAny(MetaDelimiters) >= 0;

    /// <summary>检查参数展示段是否含 @cmds 分隔符(例如字符串默认值带逗号), 返回问题描述或 null。 </summary>
    internal static string? FindMetaProblem(List<ParamSpec> specs)
    {
        foreach (var p in specs)
            if (HasMetaDelimiters(p.Display))
                return $"parameter '{p.Name}' display contains a reserved @cmds delimiter: {p.Display}";
        return null;
    }

    internal static void TryInvoke(string command)
    {
        var parts = command.Trim().Split([' '], StringSplitOptions.RemoveEmptyEntries);
        var name = parts[0];
        var args = parts.Skip(1).ToArray();

        if (!Commands.TryGetValue(name, out var cmd))
        {
            LycarionLogger.Warn(ModuleName, $"Unknown command: {name}");
            return;
        }

        cmd.Invoker(args);
    }

    // @cmds 协议: cmd~param:kind:display[:values],...;... —— 前端 parseCmds 按此解析
    internal static string EncodeCommandMeta() =>
        $"@cmds|{string.Join(";", Commands.Values.Select(EncodeCommand))}";

    internal const string DefaultGroup = "General";

    /// <summary>分组命令列表(help 输出): 显式分组按注册序在前, 未分组(General)最后. </summary>
    internal static string FormatHelpList()
    {
        var groups = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
        var order = new List<string>();
        foreach (var cmd in Commands.Values)
        {
            var groupName = string.IsNullOrEmpty(cmd.Group) ? DefaultGroup : cmd.Group!;
            if (!groups.TryGetValue(groupName, out var names))
            {
                names = new List<string>();
                groups[groupName] = names;
                order.Add(groupName);
            }
            names.Add(cmd.Name);
        }

        var sb = new StringBuilder();
        foreach (var g in order)
        {
            if (string.Equals(g, DefaultGroup, StringComparison.OrdinalIgnoreCase))
                continue;
            sb.Append('[').Append(g).Append(']').Append('\n');
            sb.Append("  ").Append(string.Join(", ", groups[g])).Append('\n');
        }
        if (groups.TryGetValue(DefaultGroup, out var general))
        {
            sb.Append('[').Append(DefaultGroup).Append(']').Append('\n');
            sb.Append("  ").Append(string.Join(", ", general)).Append('\n');
        }
        return sb.ToString().TrimEnd('\n', '\r');
    }

    static string EncodeCommand(Command c)
    {
        if (c.CompletionParams.Count == 0)
            return c.Name;
        var ps = c.CompletionParams.Select(p =>
            p.Kind == "enum"
                ? $"{p.Name}:enum:{p.Display}:{string.Join("|", p.Values!)}"
                : $"{p.Name}:{p.Kind}:{p.Display}");
        return $"{c.Name}~{string.Join(",", ps)}";
    }
}
#endregion

#region file: InternalCommands.cs
file static class InternalCommands
{
    [LoggerCommand("setLevel", "set LogLevel", "Internal")]
    public static void SetLogLevel(LycarionLogLevel logLevel)
    {
        LycarionLogger.Level = logLevel;
        string level = logLevel switch
        {
            LycarionLogLevel.Verbose => "Verbose",
            LycarionLogLevel.Debug => "Debug",
            LycarionLogLevel.Info => "Info",
            LycarionLogLevel.Warn => "Warn",
            LycarionLogLevel.Error => "Error",
            _ => "Info"
        };
        LycarionLogger.Log(logLevel, $"Log level set to {level}");
    }

    [LoggerCommand("clear", "clear Logger", "Internal")]
    public static void Clear()
    {
        WebSocketServer.ClearHistory();
        _ = WebSocketServer.BroadcastAsync("@clear", false);
    }

    [LoggerCommand("echo", "echo input", "Internal")]
    public static void Echo(RawString msg) => LycarionLogger.Raw(msg);

    [LoggerCommand("help", "show description for given command", "Internal")]
    public static void Help(string? name = null)
    {
        if (string.IsNullOrEmpty(name))
        {
            LycarionLogger.Raw($"Available commands:\n{LoggerCommandRegistry.FormatHelpList()}\n\nType 'help <commandName>' for details.");
            return;
        }

        if (!LoggerCommandRegistry.Commands.TryGetValue(name!, out var cmd))
        {
            LycarionLogger.Warn(LoggerCommandRegistry.ModuleName, $"Command {name} not found in registry");
            return;
        }

        var groupName = string.IsNullOrEmpty(cmd.Group) ? LoggerCommandRegistry.DefaultGroup : cmd.Group!;
        LycarionLogger.Raw($"[{groupName}] {name}: ({string.Join(", ", cmd.ParameterInfo)})\n{cmd.Description}");
    }

    [LoggerCommand("status", "show server status", "Internal")]
    public static void Status() => LycarionLogger.Raw(FormatStatus());

    internal static string FormatStatus()
    {
        var up = DateTime.UtcNow - LycarionLogger.StartupUtc;
        string uptime = up.TotalHours >= 1
            ? $"{(int)up.TotalHours}h {up.Minutes}m"
            : up.TotalMinutes >= 1
                ? $"{(int)up.TotalMinutes}m {up.Seconds}s"
                : $"{up.Seconds}s";
        return $"level: {LycarionLogger.Level}, port: {WebSocketServer.Port}, clients: {WebSocketServer.ClientCount}, " +
               $"history: {LogHistory.Count}/{LogHistory.Capacity}, queue: {LycarionLogger.QueueCount}/10000, uptime: {uptime}";
    }

    [LoggerCommand("gc", "trigger GC and report memory", "Internal")]
    public static void Gc()
    {
        long before = GC.GetTotalMemory(false);
        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();
        long after = GC.GetTotalMemory(true);
        LycarionLogger.Raw($"collected: {FormatBytes(Math.Max(0, before - after))}, total: {FormatBytes(after)}, working set: {FormatBytes(Environment.WorkingSet)}");
    }

    static string FormatBytes(long b)
    {
        if (b >= 1024 * 1024)
            return $"{b / 1024.0 / 1024.0:F1} MB";
        if (b >= 1024)
            return $"{b / 1024.0:F1} KB";
        return $"{b} B";
    }

    [LoggerCommand("test", "log one message at each level", "Internal")]
    public static void Test()
    {
        // 临时放开到 Verbose, 保证 5 级全输出(验证显示管线而非级别过滤), 执行完恢复
        var saved = LycarionLogger.Level;
        LycarionLogger.Level = LycarionLogLevel.Verbose;
        try
        {
            LycarionLogger.Verbose("Test", "verbose message");
            LycarionLogger.Debug("Test", "debug message");
            LycarionLogger.Info("Test", "info message");
            LycarionLogger.Warn("Test", "warn message");
            LycarionLogger.Error("Test", "error message");
        }
        finally { LycarionLogger.Level = saved; }
    }
}
#endregion

#region file: LogHistory.cs
/// <summary>环形历史：保留最近 2000 条已广播的行。 </summary>
file static class LogHistory
{
    private const int Max = 2000;
    private static readonly string[] buffer = new string[Max];
    private static int head;
    private static int count;

    internal static int Count { get { lock (buffer) return count; } }
    internal static int Capacity => Max;

    public static void Add(string line)
    {
        lock (buffer)
        {
            buffer[head] = line;
            head = (head + 1) % Max;
            if (count < Max)
                count++;
        }
    }

    public static List<string> Snapshot()
    {
        lock (buffer)
        {
            var list = new List<string>(count);
            int start = count < Max ? 0 : head;   // 环满时最旧元素在 head
            for (int i = 0; i < count; i++)
                list.Add(buffer[(start + i) % Max]);
            return list;
        }
    }

    public static void Clear()
    {
        lock (buffer)
        {
            head = 0;
            count = 0;
        }
    }
}
#endregion

#region file: WebSocketFrame.cs
file static class WebSocketFrame
{
    /// <summary>构建服务端关闭帧（携带 1000 Normal Closure，浏览器据此识别正常关闭）。 </summary>
    public static byte[] BuildCloseFrame() => [0x88, 0x02, 0x03, 0xE8];

    /// <summary>构建服务端文本帧（RFC 6455 服务端帧不掩码）。 </summary>
    public static byte[] BuildTextFrame(string msg)
    {
        // 精确计算负载字节数一次分配；不用 ArrayPool, 保证零依赖发布
        int payloadLen = Encoding.UTF8.GetByteCount(msg);
        int headerLen = payloadLen <= 125 ? 2 : (payloadLen <= ushort.MaxValue ? 4 : 10);
        byte[] frame = new byte[headerLen + payloadLen];

        frame[0] = 0x81;
        if (payloadLen <= 125)
        {
            frame[1] = (byte)payloadLen;
        }
        else if (payloadLen <= ushort.MaxValue)
        {
            frame[1] = 126;
            frame[2] = (byte)((payloadLen >> 8) & 0xFF);
            frame[3] = (byte)(payloadLen & 0xFF);
        }
        else
        {
            frame[1] = 127;
            ulong ulen = (ulong)payloadLen;
            for (int i = 0; i < 8; i++)
                frame[9 - i] = (byte)((ulen >> (8 * i)) & 0xFF);
        }

        Encoding.UTF8.GetBytes(msg, 0, msg.Length, frame, headerLen);
        return frame;
    }

    private const int MaxFrameBytes = 1 << 20;   // 帧负载上限 1 MiB, 防超大帧攻击

    /// <summary>读取客户端文本帧（必须掩码）。返回 null 表示关闭/非文本/未掩码/超限/EOF；pong 帧会被跳过。 </summary>
    public static async Task<string?> ReadClientTextFrame(Stream stream)
    {
        while (true)
        {
            byte[] header = new byte[2];
            try { await stream.ReadExactlyAsync(header, 0, 2); }
            catch (EndOfStreamException) { return null; }

            int opcode = header[0] & 0x0F;
            bool masked = (header[1] & 0x80) != 0;
            int len = header[1] & 0x7F;

            if (opcode == 0x8)
                return null;
            if (opcode != 0x1 && opcode != 0xA)
                return null;

            if (len == 126)
            {
                byte[] ext = new byte[2];
                await stream.ReadExactlyAsync(ext, 0, 2);
                len = (ext[0] << 8) | ext[1];
            }
            else if (len == 127)
            {
                byte[] ext = new byte[8];
                await stream.ReadExactlyAsync(ext, 0, 8);
                // 显式 LINQ: net8+ 下 ext.Reverse() 会绑定 MemoryExtensions.Reverse(Span) 并返回 void
                ulong ulen = BitConverter.ToUInt64(Enumerable.Reverse(ext).ToArray(), 0);
                if (ulen > MaxFrameBytes)   // 超限在强转前拒绝, 否则 (int) 溢出成负数可绕过 len 检查
                    return null;
                len = (int)ulen;
            }

            if (opcode == 0xA)
            {
                // pong(浏览器自动应答服务端 ping): 消费帧体后继续等下一帧, 不得视为连接关闭
                if (masked)
                    await stream.ReadExactlyAsync(new byte[4], 0, 4);
                if (len > 0)
                {
                    byte[] discard = new byte[len];
                    await stream.ReadExactlyAsync(discard, 0, len);
                }
                continue;
            }

            if (!masked)
                return null;
            if (len > MaxFrameBytes)
                return null;

            byte[] mask = new byte[4];
            await stream.ReadExactlyAsync(mask, 0, 4);

            byte[] payload = new byte[len];
            await stream.ReadExactlyAsync(payload, 0, len);

            // 按 4 字节块 XOR 解掩码
            int maskInt = BitConverter.ToInt32(mask, 0);
            int i = 0;
            for (; i <= len - 4; i += 4)
            {
                int pInt = BitConverter.ToInt32(payload, i);
                pInt ^= maskInt;
                byte[] temp = BitConverter.GetBytes(pInt);
                Buffer.BlockCopy(temp, 0, payload, i, 4);
            }
            for (; i < len; i++)
                payload[i] ^= mask[i % 4];

            return Encoding.UTF8.GetString(payload);
        }
    }

    // netstandard2.0 没有 Stream.ReadExactlyAsync, 手写补齐
    public static async Task ReadExactlyAsync(this Stream stream, byte[] buffer, int offset, int count, CancellationToken ct = default)
    {
        int totalRead = 0;
        while (totalRead < count)
        {
            int read = await stream.ReadAsync(buffer, offset + totalRead, count - totalRead, ct).ConfigureAwait(false);
            if (read == 0)
                throw new EndOfStreamException($"Cannot read all bytes, expect:{count} bytes, actual: {totalRead} bytes.");

            totalRead += read;
        }
    }
}
#endregion

#region file: WebSocketHandshake.cs
file static class WebSocketHandshake
{
    private const string Magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";   // RFC 6455 握手魔数

    public static string ComputeAccept(string key)
    {
        using var sha1 = SHA1.Create();
        var hash = sha1.ComputeHash(Encoding.ASCII.GetBytes(key + Magic));
        return Convert.ToBase64String(hash);
    }

    public static string BuildAcceptResponse(string key) =>
        $"HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {ComputeAccept(key)}\r\n\r\n";
}
#endregion

#region file: HttpPage.cs
/// <summary>调试页 HTTP 响应：替换 HTML 中的端口占位符。 </summary>
file static class HttpPage
{
    public static (byte[] header, byte[] body) BuildPage(int port)
    {
        byte[] body = Encoding.UTF8.GetBytes(WebPageHtml.Value.Replace("REPLACE_PORT_HERE", port.ToString()));
        string header = $"HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {body.Length}\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n";
        byte[] headerBytes = Encoding.ASCII.GetBytes(header);
        return (headerBytes, body);
    }
}
