#region file: WebSocketServer.cs
file static class WebSocketServer
{
    /// <summary>控制帧协议版本: 握手后首帧下发 @hello|&lt;version&gt;, 前端版本不匹配时提示。v2: 日志行携带显式模块/线程字段, 历史用 @hist 批量帧。 </summary>
    internal const int ProtocolVersion = 2;

    private static int wsPort;
    private static TcpListener? listener;
    private static readonly List<TcpClient> clients = new();
    private static TcpClient[] snapshot = Array.Empty<TcpClient>();   // 广播快照缓存: 连接增减时重建, 广播路径无锁读取
    private static bool running;

    internal static int Port => wsPort;
    internal static int ClientCount { get { lock (clients) return clients.Count; } }

    // 心跳参数(测试可调小): HeartbeatInterval 内无消息则发 ping; IdleTimeout 无任何活动则断开
    internal static TimeSpan HeartbeatInterval = TimeSpan.FromSeconds(30);
    internal static TimeSpan IdleTimeout = TimeSpan.FromSeconds(60);

    internal static void Start(int port)
    {
        if (running)
            return;

        listener = new TcpListener(IPAddress.Loopback, port);
        listener.Start();
        wsPort = ((IPEndPoint)listener.LocalEndpoint).Port;   // port=0 时取 OS 实际分配端口
        running = true;

        _ = AcceptLoop();
    }

    internal static void Stop()
    {
        running = false;
        listener?.Stop();

        lock (clients)
        {
            var closeFrame = WebSocketFrame.BuildCloseFrame();
            foreach (var c in clients)
            {
                try
                {
                    // 优雅关闭: 先发 close 帧(code 1000), 前端据此不显示断连提示; 慢客户端最多等 500ms, 超时放弃
                    using var cts = new CancellationTokenSource(500);
                    c.GetStream().WriteAsync(closeFrame, 0, closeFrame.Length, cts.Token).Wait(500);
                    // linger 2s 让 OS 发完发送缓冲: 立即 Close 会丢弃最后写入的帧
                    c.Client.LingerState = new LingerOption(true, 2);
                }
                catch { }
                c.Dispose();
            }
            clients.Clear();
            snapshot = Array.Empty<TcpClient>();
        }
    }

    /// <summary>广播一帧（可选写入历史）：逐客户端并行写，慢客户端由写超时踢除。 </summary>
    internal static async Task BroadcastAsync(string msg, bool addToHistory = true)
    {
        if (addToHistory)
            LogHistory.Add(msg);

        var frame = WebSocketFrame.BuildTextFrame(msg);
        var targets = snapshot;   // 无锁读取快照
        if (targets.Length == 0)
            return;
        await Task.WhenAll(targets.Select(c => WriteClientAsync(c, frame)));
    }

    static async Task WriteClientAsync(TcpClient c, byte[] frame)
    {
        // 每帧写超时 2s: 慢客户端(TCP 背压)写不完视为掉线踢除, 否则拖死整个 WhenAll 广播
        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(2));
        try { await c.GetStream().WriteAsync(frame, 0, frame.Length, cts.Token); }
        catch
        {
            lock (clients)
            {
                clients.Remove(c);
                c.Dispose();
                snapshot = clients.ToArray();
            }
        }
    }

    internal static void ClearHistory() => LogHistory.Clear();

    private static async Task AcceptLoop()
    {
        if (listener == null)
            return;

        while (running)
        {
            var client = await listener.AcceptTcpClientAsync();
            _ = HandleClient(client);
        }
    }

    private static async Task HandleClient(TcpClient client)
    {
        using var stream = client.GetStream();
        using var reader = new StreamReader(stream, Encoding.UTF8);

        string? requestLine = await reader.ReadLineAsync();
        if (string.IsNullOrEmpty(requestLine))
            return;

        if (!requestLine.StartsWith("GET", StringComparison.OrdinalIgnoreCase))
        {
            // 仅支持 GET(调试页 / WebSocket 握手), 其余方法 405
            byte[] bad = Encoding.ASCII.GetBytes("HTTP/1.1 405 Method Not Allowed\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");
            await stream.WriteAsync(bad, 0, bad.Length);
            return;
        }

        if (requestLine.StartsWith("GET /notify", StringComparison.OrdinalIgnoreCase))
        {
            // 跨进程端口占用提醒: 另一实例 Initialize 失败时经此路径广播 Warn [Server]
            // 走 HTTP 而不进命令表: 浏览器无法伪造, 也无需 WebSocket 握手/掩码帧
            var path = requestLine.Split(' ')[1];
            var query = path.Contains('?') ? path.Substring(path.IndexOf('?') + 1) : "";
            var message = query.StartsWith("m=") ? Uri.UnescapeDataString(query.Substring(2)) : "";
            LycarionLogger.Warn("Server", message);
            byte[] ok = Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n");
            await stream.WriteAsync(ok, 0, ok.Length);
            return;
        }

        if (requestLine.StartsWith("GET / ", StringComparison.OrdinalIgnoreCase) || requestLine.StartsWith("GET /HTTP", StringComparison.OrdinalIgnoreCase))
        {
            string? line;
            while (!string.IsNullOrEmpty(line = await reader.ReadLineAsync())) { }

            var (pageHeader, pageBody) = HttpPage.BuildPage(wsPort);
            await stream.WriteAsync(pageHeader, 0, pageHeader.Length);
            await stream.WriteAsync(pageBody, 0, pageBody.Length);
            return;
        }

        string? line2;
        string wsKey = string.Empty;

        while (!string.IsNullOrEmpty(line2 = await reader.ReadLineAsync()))
        {
            if (line2.StartsWith("Sec-WebSocket-Key", StringComparison.OrdinalIgnoreCase))
                wsKey = line2.Split(':')[1].Trim();
        }

        if (wsKey == string.Empty)
            return;

        byte[] respBytes = Encoding.ASCII.GetBytes(WebSocketHandshake.BuildAcceptResponse(wsKey));
        await stream.WriteAsync(respBytes, 0, respBytes.Length);

        // 协议版本 → 命令元数据 → 历史快照, 顺序由前端按此消费
        var helloFrame = WebSocketFrame.BuildTextFrame($"@hello|{ProtocolVersion}");
        await stream.WriteAsync(helloFrame, 0, helloFrame.Length);

        var cmds = LoggerCommandRegistry.EncodeCommandMeta();
        var cmdsFrame = WebSocketFrame.BuildTextFrame(cmds);
        await stream.WriteAsync(cmdsFrame, 0, cmdsFrame.Length);

        // 历史合并成单个 @hist 帧: 每行前缀 UTF-16 长度(<len>:<line>), 与 JS string.length 一致
        var history = LogHistory.Snapshot();
        if (history.Count > 0)
        {
            var payload = new StringBuilder("@hist|");
            foreach (var line in history)
                payload.Append(line.Length).Append(':').Append(line);
            var histFrame = WebSocketFrame.BuildTextFrame(payload.ToString());
            await stream.WriteAsync(histFrame, 0, histFrame.Length);
        }

        // 注册在历史补发之后: 新客户端先拿到完整快照再进入广播集合, 避免补发期间重复收到日志
        lock (clients)
        {
            clients.Add(client);
            snapshot = clients.ToArray();
        }

        try
        {
            // 心跳: HeartbeatInterval 内无消息发 ping(0x89); IdleTimeout 无活动则断连(防网络设备静默断开)
            // 注意: readTask 跨循环复用——ping 分支不得重启读任务, 否则两个 ReadClientTextFrame 并发读同一流,
            //       命令帧可能被遗弃的旧任务消费而丢失(pong 存活后此竞争必然暴露)
            var activity = DateTime.UtcNow;
            var readTask = WebSocketFrame.ReadClientTextFrame(stream);
            while (client.Connected)
            {
                var pingDelay = Task.Delay(HeartbeatInterval);
                var done = await Task.WhenAny(readTask, pingDelay);

                if (done == readTask)
                {
                    var msg = await readTask;
                    activity = DateTime.UtcNow;
                    if (msg == null)
                    {
                        // 对端关闭/EOF: 回 close 帧后收尾
                        var closeFrame = WebSocketFrame.BuildCloseFrame();
                        try { await stream.WriteAsync(closeFrame, 0, closeFrame.Length); }
                        catch { }
                        break;
                    }

                    LoggerCommandRegistry.TryInvoke(msg);
                    readTask = WebSocketFrame.ReadClientTextFrame(stream);
                }
                else if ((DateTime.UtcNow - activity) > IdleTimeout)
                {
                    break;
                }
                else
                {
                    byte[] ping = [0x89, 0x00];
                    try { await stream.WriteAsync(ping, 0, ping.Length); }
                    catch { break; }
                }
            }
        }
        catch { }

        lock (clients)
        {
            clients.Remove(client);
            snapshot = clients.ToArray();
        }

        client.Close();
    }
}
#endregion

#region resource
file static class WebPageHtml
{
    internal const string Value = @"<!DOCTYPE html>
