</head>
<body>
<div id='statusbar'>
  <span id='conn' class='conn down' title='connection'>●</span>
  <span class='levels'>
    <button class='lv on' data-level='Verbose' title='Verbose'>V</button>
    <button class='lv on' data-level='Debug' title='Debug'>D</button>
    <button class='lv on' data-level='Info' title='Info'>I</button>
    <button class='lv on' data-level='Warn' title='Warn'>W</button>
    <button class='lv on' data-level='Error' title='Error'>E</button>
  </span>
  <input id='modfilter' placeholder='module' title='module filter' />
