</div>
<div id='log'></div>
<div id='hint'></div>
<div id='input'>
  <input id='cmd' placeholder='type help for all commands...' />
</div>

<script>
// 调试页脚本: WebSocket 连接/重连、日志渲染与过滤、命令控制台。
// 协议见 docs/ARCHITECTURE.md（行格式 §4.3, 握手与控制帧 §6.2）
const maxLines = 2000;
const log = document.getElementById('log');
const input = document.getElementById('cmd');
const connDot = document.getElementById('conn');
const modFilter = document.getElementById('modfilter');
const searchBox = document.getElementById('search');
const exportBtn = document.getElementById('export');
const hint = document.getElementById('hint');

const maxHistory = 200;
const history = [];
let historyIndex = -1;

let allCommands = [];
let lastTabInput = '';
let matchIndex = 0;

let levelOn = {Verbose:true, Debug:true, Info:true, Warn:true, Error:true};
let moduleFilter = '';
let searchQuery = '';
let pending = [];
let renderTimer = null;
let filterTimer = null;
let logBuffer = [];      // 已接收的结构化行: 过滤条件变化时据此重渲染
const renderInterval = 40;

function filters() { return {levelOn, moduleFilter, searchQuery}; }

// ===== 连接与自动重连 =====
let ws = null;
let reconnectDelay = 1000;
let wasConnected = false;   // 当前连接是否活着(断连提示判定)
let hadSession = false;     // 是否成功连接过(重连提示/宽限期判定)
let reconnectDeadline = 0;  // 重连宽限截止时间(0 = 尚未开始计时)
const RECONNECT_GRACE_MS = 60000;   // 连接成功后断开: 1 分钟内自动重试, 超时放弃
const protocolVersion = 2;          // 与服务端 @hello|N 校验, 不匹配时提示刷新
const wsUrl = 'ws://localhost:REPLACE_PORT_HERE/ws';

function connect()
{
    setConn('reconnecting');
    ws = new WebSocket(wsUrl);
    ws.onopen = () =>
    {
        // 服务端会重新补发历史快照: 先清空避免重复(先清后插, 提示行才保留)
        log.innerHTML = '';
        // 断开后再次连上 = 重连(新会话) 才插提示; 首次连接不插
        if (hadSession && !wasConnected)
            insertReconnectHint();
        hadSession = true;
        wasConnected = true;
        reconnectDeadline = 0;   // 连接成功重置宽限
        setConn('ok');
        reconnectDelay = 1000;
    };
    ws.onclose = (ev) =>
    {
        // 仅已连接过的场景才计宽限: 初始连不上会一直重试
        if (hadSession && reconnectDeadline === 0)
            reconnectDeadline = Date.now() + RECONNECT_GRACE_MS;
        setConn('down');
        // code 1000 = 服务端正常关闭(已广播 shutdown): 不显示断连提示
        if (ev && ev.code === 1000)
        {
            wasConnected = false;
            scheduleReconnect();
            return;
        }
        if (wasConnected)
        {
            wasConnected = false;
            insertDisconnectHint();   // 仅已连接后断开才插, 避免初始/重连失败循环刷屏
        }
        scheduleReconnect();
    };
    ws.onerror = () => { try { ws.close(); } catch {} };
    ws.onmessage = ev => handleMessage(ev.data);
}

// 断连提示(本地 UI 行, 不进 logBuffer, 豁免裁剪): 宿主退出/网络断开时的视觉反馈
function insertDisconnectHint()
{
    flush();   // 先渲染 pending, 提示行才能位于日志最后
    const row = document.createElement('div');
    row.className = 'logline disc';
    const body = document.createElement('span');
    body.className = 'msg';
    body.textContent = '--- disconnected, reconnecting... ---';
    row.appendChild(body);
    log.appendChild(row);
    trimLog();
}

// 重连提示: 宿主重启/网络恢复后新会话开始的标记
function insertReconnectHint()
{
    const row = document.createElement('div');
    row.className = 'logline reconn';
    const body = document.createElement('span');
    body.className = 'msg';
    body.textContent = '--- reconnected ---';
    row.appendChild(body);
    log.appendChild(row);
    trimLog();
}

// 协议版本不匹配提示(本地 UI 行, 不进 logBuffer): 缓存页面/旧页面连到新协议服务端时可见
function insertProtocolHint(version)
{
    flush();   // 先渲染 pending, 提示行才能位于日志最后
    const row = document.createElement('div');
    row.className = 'logline disc';
    const body = document.createElement('span');
    body.className = 'msg';
    body.textContent = '--- unsupported protocol v' + version + ', page expects v' + protocolVersion + '; refresh page ---';
    row.appendChild(body);
    log.appendChild(row);
    trimLog();
}

// 统一裁剪: 超过 maxLines 时删除最旧日志行, 但保留断连/重连提示行(.disc/.reconn)
function trimLog()
{
    while (log.children.length > maxLines)
    {
        const victims = [...log.children].filter(c => !c.className.includes('disc') && !c.className.includes('reconn'));
        if (victims.length === 0)
            break;
        log.removeChild(victims[0]);
    }
}

function scheduleReconnect()
{
    // 宽限期耗尽: 放弃自动重连(仅刷新页面恢复), 插提示告知
    if (hadSession && Date.now() > reconnectDeadline)
    {
        insertStoppedHint();
        return;
    }
    setTimeout(connect, reconnectDelay);
    reconnectDelay = Math.min(reconnectDelay * 2, 30000);
}

// 放弃重连提示(本地 UI 行, 豁免裁剪)
function insertStoppedHint()
{
    flush();   // 先渲染 pending, 提示行才能位于日志最后
    const row = document.createElement('div');
    row.className = 'logline disc';
    const body = document.createElement('span');
    body.className = 'msg';
    body.textContent = '--- reconnecting stopped after 1 min, refresh page to retry ---';
    row.appendChild(body);
    log.appendChild(row);
    trimLog();
}

function setConn(state)
{
    connDot.className = 'conn ' + state;
}

// ===== 消息处理 + 渲染节流 =====
// 控制帧: @clear / @hello|N / @hist|... / @cmds|...; 其余按协议 v2 日志行入队
function handleMessage(raw)
{
    if (raw === '@clear') { clearLog(); return; }
    if (raw.startsWith('@hello|')) { onHello(raw); return; }
    if (raw.startsWith('@hist|')) { pending.push(...parseHistory(raw)); scheduleRender(); return; }
    if (raw.startsWith('@cmds|')) { allCommands = parseCmds(raw); return; }
    pending.push(raw);
    scheduleRender();
}

// 清屏: DOM、缓冲与未渲染队列都要清, 否则切换过滤条件时旧日志会被重新渲染
function clearLog()
{
    log.innerHTML = '';
    logBuffer.length = 0;
    pending.length = 0;
}

// 协议版本校验: 页面与服务端通常同源, 但缓存/旧页面可能版本不一致
function onHello(raw)
{
    const version = parseHello(raw);
    if (version !== protocolVersion)
        insertProtocolHint(version);
}

function scheduleRender()
{
    if (renderTimer) return;
    renderTimer = setTimeout(() => { renderTimer = null; flush(); }, renderInterval);
}

function flush()
{
    const batch = pending.splice(0, pending.length);
    if (batch.length === 0) return;
    const frag = document.createDocumentFragment();
    for (const raw of batch)
    {
        const line = parseLine(raw);
        if (!line) continue;
        logBuffer.push(line);
        if (logBuffer.length > maxLines)
            logBuffer.shift();
        if (!shouldRender(line, filters())) continue;
        frag.appendChild(buildLineDom(line));
    }
    const stick = isAtBottom();
    log.appendChild(frag);
    trimLog();
    // 吸底: 仅在底部时自动滚动(上翻阅读时不打扰)
    if (stick)
        log.scrollTop = log.scrollHeight;
}

// 过滤条件变化: 清空并按当前条件重渲染全部缓冲日志(搜索/级别/模块即时生效)
function renderAll()
{
    log.innerHTML = '';
    const frag = document.createDocumentFragment();
    for (const line of logBuffer)
        if (shouldRender(line, filters()))
            frag.appendChild(buildLineDom(line));
    log.appendChild(frag);
    log.scrollTop = 0;
}

function scheduleRenderAll()
{
    if (filterTimer) clearTimeout(filterTimer);
    filterTimer = setTimeout(() => { filterTimer = null; renderAll(); }, 200);
}

// ===== 纯逻辑(可单测) =====
// 模块名 -> 稳定颜色(同名同色), 色板在暗色背景下均可读
const moduleColorPalette = ['#64d8cb', '#ffcb6b', '#82aaff', '#c792ea', '#f78c6c', '#89ddff', '#addb67', '#ff9e64'];
const moduleColorCache = new Map();
function moduleColor(name)
{
    let color = moduleColorCache.get(name);
    if (color) return color;
    let hash = 0;
    for (let i = 0; i < name.length; i++)
        hash = (hash * 31 + name.charCodeAt(i)) >>> 0;
    color = moduleColorPalette[hash % moduleColorPalette.length];
    moduleColorCache.set(name, color);
    return color;
}

// 解析 @hello|N 协议版本帧; 非版本帧或非法版本返回 null
function parseHello(raw)
{
    if (!raw.startsWith('@hello|')) return null;
    const v = parseInt(raw.substring('@hello|'.length), 10);
    return isNaN(v) ? null : v;
}

function parseCmds(raw)
{
    // 协议前缀 | 后是命令列表(枚举值也用 | 分隔, 只能定位第一个 |)
    const spec = raw.substring(raw.indexOf('|') + 1);
    if (!spec) return [];
    return spec.split(';').filter(Boolean).map(cmdStr =>
    {
        const [name, paramsStr] = cmdStr.split('~');
        const params = paramsStr ? paramsStr.split(',').map(p =>
        {
            // name:kind:display[:values](display 为 C# 风格展示段, 如 ""int i = 286"")
            const [pname, kind, display, valuesStr] = p.split(':');
            const values = valuesStr ? valuesStr.split('|') : null;
            return {name: pname, kind, display, values};
        }) : [];
        return {name, params};
    });
}

// 参数提示条: 显示命令参数(名/类型/枚举值/默认值), 当前参数 ▶ 标记
function hintFor(input, commands)
{
    const parts = input.trim().split(/\s+/).filter(Boolean);
    if (parts.length === 0) return '';   // 空输入不提示(placeholder 已有引导)
    const cmd = commands.find(c => c.name === parts[0]);
    if (!cmd) return '';
    // 超过参数数量时 ▶ 锁定在最后一个参数
    const paramIndex = Math.min(parts.length - 1, cmd.params.length - 1);
    return cmd.params.map((p, i) =>
    {
        let s = p.display || (p.name + ': ' + p.kind);   // C# 风格展示(与 help 输出一致)
        if (p.values) s += ' (' + p.values.join('|') + ')';
        return (i === paramIndex ? '▶ ' : '') + s;
    }).join('   ');
}

function updateHint()
{
    const h = hintFor(input.value, allCommands);
    hint.textContent = h;
    hint.style.display = h ? 'block' : 'none';
}

// Tab 循环补全: 调用方用 lastTabInput / matchIndex 记录上一轮匹配状态
function completeTab(input, commands, lastTabInput, matchIndex)
{
    const parts = input.split(' ').filter(Boolean);
    if (parts.length === 0) return null;
    const cmdName = parts[0];
    const current = parts[parts.length - 1];
    const base = lastTabInput || current;

    if (parts.length === 1)
    {
        const matches = commands.map(c => c.name).filter(n => n.startsWith(base));
        if (matches.length === 0) return null;
        return {value: matches[matchIndex % matches.length], lastTabInput: base, matchIndex: matchIndex + 1};
    }

    const cmd = commands.find(c => c.name === cmdName);
    if (!cmd) return null;
    const paramIndex = parts.length - 2;
    const param = cmd.params[paramIndex];
    if (!param) return null;
    let candidates;
    if (param.kind === 'enum') candidates = param.values.filter(v => v.toLowerCase().startsWith(current.toLowerCase()));
    else if (param.kind === 'bool') candidates = ['true', 'false'].filter(v => v.startsWith(current));
    else return null;
    if (candidates.length === 0) return null;
    const value = parts.slice(0, -1).join(' ') + ' ' + candidates[matchIndex % candidates.length];
    return {value, lastTabInput: base, matchIndex: matchIndex + 1};
}

// 协议 v2 日志行: 级别|时间|线程|模块|raw标记|消息
// 模块字段转义(见 LogEntry.EscapeField): \| \\ \n \r
function unescapeField(field)
{
    return field.replace(/\\(.)/g, (_, c) => c === 'n' ? '\n' : c === 'r' ? '\r' : c);
}

// 找下一个未转义的分隔符(模块字段里的 \| 不算分隔)
function nextSeparator(raw, from)
{
    for (let i = from; i < raw.length; i++)
    {
        if (raw[i] === '\\') { i++; continue; }
        if (raw[i] === '|') return i;
    }
    return -1;
}

function parseLine(raw)
{
    let pos = raw.indexOf('|');
    if (pos < 0) return null;
    const level = raw.substring(0, pos);
    const fields = [];
    for (let i = 0; i < 4; i++)   // 依次取: 时间/线程/模块/raw 标记
    {
        const next = nextSeparator(raw, pos + 1);
        if (next < 0) return null;
        fields.push(raw.substring(pos + 1, next));
        pos = next;
    }
    const [time, thread, module, rawFlag] = fields;
    return {
        level,
        time: time || null,
        thread: thread ? parseInt(thread, 10) : null,
        module: module ? unescapeField(module) : null,
        raw: rawFlag === '1',
        msg: raw.substring(pos + 1)
    };
}

// @hist| 历史批量帧: 每行前缀 UTF-16 长度(<len>:<line>), 与 JS string.length 一致
function parseHistory(raw)
{
    const payload = raw.substring('@hist|'.length);
    const lines = [];
    let pos = 0;
    while (pos < payload.length)
    {
        const colon = payload.indexOf(':', pos);
        if (colon < 0) break;
        const len = parseInt(payload.substring(pos, colon), 10);
        if (isNaN(len) || len < 0) break;
        lines.push(payload.substring(colon + 1, colon + 1 + len));
        pos = colon + 1 + len;
    }
    return lines;
}

function shouldRender(line, filters)
{
    if (!filters.levelOn[line.level]) return false;
    if (filters.moduleFilter && line.module && line.module.toLowerCase().indexOf(filters.moduleFilter.toLowerCase()) < 0) return false;
    if (filters.searchQuery && !line.msg.toLowerCase().includes(filters.searchQuery)) return false;
    return true;
}

function isAtBottom()
{
    return log.scrollHeight - log.scrollTop - log.clientHeight < 5;
}

function buildLineDom(line)
{
    const row = document.createElement('div');
    row.className = 'logline ' + line.level.toLowerCase()[0];
    if (line.raw)   // Raw 行(命令回显/系统输出): 只显示消息正文
    {
        const rawBody = document.createElement('span');
        rawBody.className = 'msg';
        rawBody.textContent = line.msg;
        row.appendChild(rawBody);
        return row;
    }
    if (line.time)
    {
        const t = document.createElement('span');
        t.className = 'ts';
        t.textContent = line.time;
        row.appendChild(t);
    }
    if (line.thread !== null)
    {
        const thr = document.createElement('span');
        thr.className = 'thr';
        thr.textContent = 'T:' + line.thread;
        row.appendChild(thr);
    }
    const badge = document.createElement('span');
    badge.className = 'badge ' + line.level.toLowerCase()[0];
    badge.textContent = line.level.toUpperCase();
    row.appendChild(badge);
    if (line.module)
    {
        const mod = document.createElement('span');
        mod.className = 'mod';
        mod.textContent = '[' + line.module + ']';
        mod.style.color = moduleColor(line.module);   // 同名模块同色
        row.appendChild(mod);
    }
    const body = document.createElement('span');
    body.className = 'msg';
    body.textContent = line.msg;
    row.appendChild(body);
    return row;
}

// ===== 输入 =====
input.addEventListener('keydown', e =>
{
    if (e.key === 'Enter')
    {
        const text = input.value.trim();
        if (!text) return;

        ws.send(text);
        echoCommand('▶ ' + text);

        if (history.length === 0 || history[history.length - 1] !== text)
        {
            history.push(text);
            if (history.length > maxHistory)
                history.shift();
        }
        historyIndex = -1;
        input.value = '';
        updateHint();
        e.preventDefault();
        return;
    }

    if (e.key === 'ArrowUp')
    {
        if (history.length === 0) return;
        if (historyIndex < 0)
            historyIndex = history.length - 1;
        else if (historyIndex > 0)
            historyIndex--;
        input.value = history[historyIndex];
        e.preventDefault();
        return;
    }

    if (e.key === 'ArrowDown')
    {
        if (historyIndex < 0) return;
        historyIndex++;
        if (historyIndex >= history.length)
        {
            historyIndex = -1;
            input.value = '';
        }
        else
        {
            input.value = history[historyIndex];
        }
        e.preventDefault();
        return;
    }

    if (e.key === 'Tab')
    {
        e.preventDefault();
        const currentInput = input.value;
        if (currentInput === '') return;

        const result = completeTab(currentInput, allCommands, lastTabInput, matchIndex);
        if (result)
        {
            input.value = result.value;
            lastTabInput = result.lastTabInput;
            matchIndex = result.matchIndex;
            updateHint();
        }
    }
    else
    {
        lastTabInput = '';   // 其它按键打断补全循环
        matchIndex = 0;
    }
});

input.addEventListener('input', updateHint);

function echoCommand(text)
{
    const row = document.createElement('div');
    row.className = 'logline cmd-echo';
    const body = document.createElement('span');
    body.textContent = text;
    row.appendChild(body);
    log.appendChild(row);
    trimLog();
}

// ===== 工具栏 =====
document.querySelectorAll('.lv').forEach(btn =>
{
    btn.addEventListener('click', () =>
    {
        const lv = btn.dataset.level;
        levelOn[lv] = !levelOn[lv];
        btn.classList.toggle('on', levelOn[lv]);
        renderAll();
    });
});

modFilter.addEventListener('input', () => { moduleFilter = modFilter.value.trim(); scheduleRenderAll(); });
searchBox.addEventListener('input', () => { searchQuery = searchBox.value.trim().toLowerCase(); scheduleRenderAll(); });

exportBtn.addEventListener('click', () =>
{
    // 手动拼接每行(innerText 会把 flex span 拆成多行, 不可读)
    const lines = [];
    for (const row of log.children)
    {
        const parts = [];
        for (const span of row.querySelectorAll('.ts,.thr,.badge,.mod,.msg'))
            parts.push(span.textContent);
        lines.push(parts.length ? parts.join(' ') : row.textContent);
    }
    const text = lines.join('\n');
    const blob = new Blob([text], {type: 'text/plain'});
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'logger-' + new Date().toISOString().replace(/[:.]/g, '-') + '.txt';
    a.click();
    URL.revokeObjectURL(a.href);
});

// ===== 快捷键 =====
document.addEventListener('keydown', e =>
{
    if (e.ctrlKey && e.key === 'l') { e.preventDefault(); log.innerHTML = ''; }
    else if (e.ctrlKey && e.key === 'f') { e.preventDefault(); searchBox.focus(); }
    else if (e.key === 'Escape') { input.value = ''; input.focus(); }
});

// 首帧连接: 启动即尝试连接, 失败按退避重试
connect();
</script>
</body>
</html>";
}
#endregion

